package main

import (
	"bytes"
	"fmt"
	"sync"
)

var bufPool = sync.Pool{
	New: func() any { return new(bytes.Buffer) }, // called only when empty
}

func main() {
	b := bufPool.Get().(*bytes.Buffer) // borrow or allocate via New
	b.WriteString("hi")
	fmt.Println(b.String())
	bufPool.Put(b) // return for the next caller
	// Output: hi
}

