package solution

import (
	"bytes"
	"strconv"
	"sync"
)

// Pooled buffers cut allocations on this hot string-building path.
var bufPool = sync.Pool{
	New: func() any { return new(bytes.Buffer) },
}

func Solve(nums []int) string {
	if len(nums) == 0 {
		return ""
	}
	buf := bufPool.Get().(*bytes.Buffer) // borrow (or New)
	buf.Reset()                          // clear any leftover bytes
	defer bufPool.Put(buf)               // return for reuse

	for i, n := range nums {
		if i > 0 {
			buf.WriteByte(',')
		}
		buf.WriteString(strconv.Itoa(n)) // append the decimal form
	}
	return buf.String() // String() copies, so it's safe after Put
}

