package solution

import "testing"

func TestSolve(t *testing.T) {
	cases := []struct {
		in   []int
		want string
	}{
		{[]int{1, 2, 3}, "1,2,3"},
		{[]int{}, ""},
		{[]int{42}, "42"},
		{[]int{-1, 0, 7}, "-1,0,7"},
	}
	for _, c := range cases {
		if got := Solve(c.in); got != c.want {
			t.Errorf("Solve(%v)=%q want %q", c.in, got, c.want)
		}
	}
}

// A second call must not see the first call's leftover bytes.
func TestSolveReusesCleanly(t *testing.T) {
	_ = Solve([]int{9, 9, 9})
	if got := Solve([]int{1}); got != "1" {
		t.Errorf("stale buffer leaked: got %q want %q", got, "1")
	}
}

