var hexPool = sync.Pool{
	New: func() any {
		b := make([]byte, 0, 64) // SHA-256 hex = 64 chars
		return &b
	},
}

func HashHex(data []byte) string {
	sum := sha256.Sum256(data)        // [32]byte, no heap alloc
	bp := hexPool.Get().(*[]byte)     // borrow scratch (or New)
	dst := (*bp)[:cap(*bp)]           // use full capacity as dest
	hex.Encode(dst, sum[:])           // write 64 hex bytes
	out := string(dst)                // string() copies the bytes
	*bp = dst[:0]                     // reset length for next user
	hexPool.Put(bp)                   // return the pointer (no alloc)
	return out
}

// BufferPool is a typed, safe wrapper over sync.Pool for *bytes.Buffer.
type BufferPool struct {
	pool   sync.Pool
	maxCap int // buffers larger than this are dropped, not pooled
}

func NewBufferPool(maxCap int) *BufferPool {
	return &BufferPool{
		pool:   sync.Pool{New: func() any { return new(bytes.Buffer) }},
		maxCap: maxCap,
	}
}

// Get returns a reset buffer, so callers never see a prior user's bytes.
func (p *BufferPool) Get() *bytes.Buffer {
	b := p.pool.Get().(*bytes.Buffer)
	b.Reset() // invariant: always clean on acquire
	return b
}

// Put returns the buffer for reuse, but drops oversized ones so the
// pool can't pin a huge backing array alive across GC cycles.
func (p *BufferPool) Put(b *bytes.Buffer) {
	if b.Cap() > p.maxCap {
		return // let the GC reclaim the giant buffer
	}
	p.pool.Put(b)
}

// Example lifecycle: borrow, use, copy out, release.
var pool = NewBufferPool(64 << 10) // 64KB cap

func Render(name string) string {
	b := pool.Get()
	defer pool.Put(b)
	b.WriteString("hello, ")
	b.WriteString(name)
	return b.String() // String copies, so it's safe after Put recycles b
}
